/* Replay captured, unchanged Blender sources through the guest GL provider.
 * Pipeline compilation is separate from the pixel tests: not every shader's
 * original Blender resources are captured by this contract. */
#define GL_GLEXT_PROTOTYPES
#include <GL/gl.h>
#include <GL/glx.h>
#include <assert.h>
#include <dirent.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
extern int lrGPUGetStatistics(uint64_t*,uint64_t*,uint64_t*);
static char *source(const char *directory,int ordinal){DIR *d=opendir(directory);assert(d);struct dirent *entry;char path[4096]={0};while((entry=readdir(d))){int pid,index,shader;if(sscanf(entry->d_name,"%d-%d-%d.glsl",&pid,&index,&shader)==3&&index==ordinal){snprintf(path,sizeof path,"%s/%s",directory,entry->d_name);break;}}closedir(d);assert(*path);FILE *f=fopen(path,"rb");assert(f&&!fseek(f,0,SEEK_END));long n=ftell(f);assert(n>0&&n<131072);rewind(f);char *s=calloc(n+1,1);assert(s&&fread(s,1,n,f)==(size_t)n);fclose(f);return s;}
static GLuint shader(GLenum type,const char *s){GLuint id=glCreateShader(type);glShaderSource(id,1,&s,NULL);glCompileShader(id);GLint ok;glGetShaderiv(id,GL_COMPILE_STATUS,&ok);if(!ok){char log[2048];glGetShaderInfoLog(id,sizeof log,NULL,log);printf("BLENDER_SHADER_COMPILE_FAIL %s\n",log);}assert(ok);return id;}
static void widget(GLuint program,int elements){glUseProgram(program);float parameters[72*4]={0};for(int i=0;i<elements/12;i++){float *p=parameters+i*48;p[0]=1;p[1]=63;p[2]=1;p[3]=63;p[4]=0;p[5]=64;p[6]=0;p[7]=64;p[8]=p[9]=4;p[12]=p[13]=p[14]=p[15]=1;p[17]=p[19]=p[21]=p[23]=1;p[42]=p[43]=1;}glUniform4fv(glGetUniformLocation(program,"parameters"),elements,parameters);float matrix[16]={2.0f/64,0,0,0,0,2.0f/64,0,0,0,0,1,0,-1,-1,0,1};glUniformMatrix4fv(glGetUniformLocation(program,"ModelViewProjectionMatrix"),1,False,matrix);glUniform3f(glGetUniformLocation(program,"checkerColorAndSize"),0,0,8);glUniform1i(glGetUniformLocation(program,"srgbTarget"),0);glClearColor(0,0,0,1);glClear(GL_COLOR_BUFFER_BIT);if(elements==72)glDrawArraysInstancedBaseInstance(GL_TRIANGLE_STRIP,0,4,1,2);else glDrawArrays(GL_TRIANGLE_STRIP,0,4);unsigned char pixel[4];glReadPixels(32,32,1,1,GL_RGBA,GL_UNSIGNED_BYTE,pixel);printf("BLENDER_WIDGET_PIXEL elements=%d rgba=%u,%u,%u,%u error=%x\n",elements,pixel[0],pixel[1],pixel[2],pixel[3],glGetError());assert(pixel[1]>250&&pixel[0]<3&&pixel[2]<3);}
int main(int argc,char **argv){setbuf(stdout,NULL);assert(argc==2);Display *d=XOpenDisplay(NULL);assert(d);int attrs[]={GLX_RGBA,GLX_DOUBLEBUFFER,GLX_DEPTH_SIZE,24,None};XVisualInfo *v=glXChooseVisual(d,DefaultScreen(d),attrs);assert(v);XSetWindowAttributes a={.colormap=XCreateColormap(d,RootWindow(d,v->screen),v->visual,AllocNone)};Window w=XCreateWindow(d,RootWindow(d,v->screen),0,0,64,64,0,v->depth,InputOutput,v->visual,CWColormap,&a);GLXContext c=glXCreateContext(d,v,NULL,True);assert(c&&glXMakeCurrent(d,w,c));GLuint vao;glGenVertexArrays(1,&vao);glBindVertexArray(vao);glViewport(0,0,64,64);unsigned passed=0;
 for(int index=0;index<32;index+=2){char *vs=source(argv[1],index),*fs=source(argv[1],index+1);GLuint vertex=shader(GL_VERTEX_SHADER,vs),fragment=shader(GL_FRAGMENT_SHADER,fs),p=glCreateProgram();glAttachShader(p,vertex);glAttachShader(p,fragment);glLinkProgram(p);GLint ok;glGetProgramiv(p,GL_LINK_STATUS,&ok);if(!ok){char log[2048];glGetProgramInfoLog(p,sizeof log,NULL,log);printf("BLENDER_PIPELINE_FAIL pair=%d %s\n",index/2,log);}else{passed++;printf("BLENDER_PIPELINE_PASS pair=%d\n",index/2);if(index==2||index==10)widget(p,index==2?12:72);}glUseProgram(0);glDeleteProgram(p);glDeleteShader(vertex);glDeleteShader(fragment);free(vs);free(fs);}
 uint64_t operations,reads,ns;assert(lrGPUGetStatistics(&operations,&reads,&ns)&&operations&&ns);printf("BLENDER_SHADER_COUNTERS operations=%llu readbacks=%llu gpu_ns=%llu\n",(unsigned long long)operations,(unsigned long long)reads,(unsigned long long)ns);printf("BLENDER_SHADER_CORPUS_RESULT pipelines=%u/16\n",passed);glDeleteVertexArrays(1,&vao);glXMakeCurrent(d,None,NULL);glXDestroyContext(d,c);XDestroyWindow(d,w);XFree(v);XCloseDisplay(d);assert(passed==16);puts("BLENDER_SHADER_CONTRACT_PASS unchanged_source=PASS Metal_pipeline=PASS widget12_GPU_pixels=PASS widget72_GPU_pixels=PASS cleanup=PASS");return 0;}
